import DashboardLayout from "@/components/DashboardLayout";
import { EmptyAdminState, LoadingBlock, QueryErrorState } from "@/components/PageStates";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { MunicipalitySwitcher } from "@/components/PublicLayout";
import { useMunicipality } from "@/contexts/MunicipalityContext";
import { trpc } from "@/lib/trpc";
import { BarChart3, Building2, CircleDollarSign, FileText, Landmark, Pencil, Plus, ReceiptText, Target, UsersRound, WalletCards, Wrench } from "lucide-react";
import { useMemo, useState } from "react";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { toast } from "sonner";
import { useLocation } from "wouter";
import MunicipalityAccessSetup from "./MunicipalityAccessSetup";
import TaxPages from "./TaxPages";
import TaxPhaseTwoPages from "./TaxPhaseTwoPages";

const currency = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const number = new Intl.NumberFormat("pt-BR");
const dateText = (date: string | Date | null | undefined) => date ? new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(date)) : "—";

function Header({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { const { activeMunicipality } = useMunicipality(); return <div className="mb-7 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#0b7a73]">{eyebrow}</p><h1 className="mt-2 font-display text-3xl font-semibold tracking-[-.04em] text-[#173c40] sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#687f82]">{description}</p></div><div className="flex flex-wrap items-center gap-3"><MunicipalitySwitcher compact />{action}</div>{!activeMunicipality && <p className="text-xs text-[#b65d54]">Selecione ou cadastre uma prefeitura para iniciar a gestão.</p>}</div>; }
function Status({ status }: { status: string }) { const styles: Record<string, string> = { planejado: "bg-[#e6effd] text-[#335f9f]", "em andamento": "bg-[#e4f3f0] text-[#087069]", concluído: "bg-[#e7f4ea] text-[#307651]", cancelado: "bg-[#feebea] text-[#af524d]", accepted: "bg-[#e6effd] text-[#335f9f]", processing: "bg-[#fff1e4] text-[#b95c26]", completed: "bg-[#e7f4ea] text-[#307651]", error: "bg-[#feebea] text-[#af524d]", duplicate: "bg-[#eef2f2] text-[#61777a]" }; return <Badge className={`border-0 text-[10px] font-bold ${styles[status] ?? "bg-[#edf4f3] text-[#5f777a]"}`}>{status}</Badge>; }
function Stat({ icon: Icon, label, value, color = "teal" }: { icon: typeof Building2; label: string; value: string; color?: "teal" | "blue" | "orange" | "green" }) { const colors = { teal: "bg-[#e4f3f0] text-[#087069]", blue: "bg-[#e6effd] text-[#345fa5]", orange: "bg-[#fff0e6] text-[#b95c26]", green: "bg-[#e7f4ea] text-[#307651]" }; return <Card className="border-[#dce9e7] bg-white"><CardContent className="p-5"><span className={`grid h-9 w-9 place-items-center rounded-xl ${colors[color]}`}><Icon className="h-4 w-4"/></span><p className="mt-5 text-[10px] font-bold uppercase tracking-[.13em] text-[#71878a]">{label}</p><p className="mt-1 font-display text-2xl font-semibold tracking-[-.04em] text-[#173c40]">{value}</p></CardContent></Card>; }
function AdminCard({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <Card className={`border-[#dce9e7] bg-white shadow-[0_10px_24px_rgba(15,68,72,.04)] ${className}`}><CardContent className="p-5 sm:p-6">{children}</CardContent></Card>; }

function IndicatorEditDialog({ indicator }: { indicator: { id: number; name: string; area: string; unit: string; description: string | null; public: boolean; active: boolean } }) { const { tenantId } = useMunicipality(); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: indicator.name, area: indicator.area, unit: indicator.unit, description: indicator.description ?? "", public: indicator.public, active: indicator.active }); const update = trpc.municipal.admin.updateIndicator.useMutation({ onSuccess: () => { if (tenantId) { utils.municipal.admin.indicators.invalidate({ tenantId }); utils.municipal.public.indicators.invalidate(); } toast.success("Indicador atualizado."); setOpen(false); }, onError: error => toast.error(error.message) }); return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button variant="outline" size="sm"><Pencil className="mr-2 h-3.5 w-3.5"/>Editar</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Editar indicador</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="space-y-2"><Label>Nome</Label><Input value={form.name} onChange={event => setForm({ ...form, name: event.target.value })}/></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Área</Label><Input value={form.area} onChange={event => setForm({ ...form, area: event.target.value })}/></div><div className="space-y-2"><Label>Unidade</Label><Input value={form.unit} onChange={event => setForm({ ...form, unit: event.target.value })}/></div></div><div className="space-y-2"><Label>Descrição</Label><Textarea value={form.description} onChange={event => setForm({ ...form, description: event.target.value })}/></div></div><DialogFooter><Button disabled={!tenantId || update.isPending} onClick={() => tenantId && update.mutate({ id: indicator.id, tenantId, ...form, description: form.description || undefined })} className="bg-[#0b6672]">Salvar alterações</Button></DialogFooter></DialogContent></Dialog>; }

function TransparencyEditDialog({ record }: { record: { id: number; type: "contract" | "bid" | "expense" | "revenue"; title: string; referenceNumber: string | null; category: string; supplier: string | null; amount: string; eventDate: string; status: string; description: string | null; public: boolean } }) { const { tenantId } = useMunicipality(); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ type: record.type, title: record.title, referenceNumber: record.referenceNumber ?? "", category: record.category, supplier: record.supplier ?? "", amount: String(record.amount), eventDate: record.eventDate, status: record.status, description: record.description ?? "", public: record.public }); const update = trpc.municipal.admin.updateTransparency.useMutation({ onSuccess: () => { if (tenantId) { utils.municipal.admin.transparency.invalidate({ tenantId }); utils.municipal.public.transparency.invalidate(); } toast.success("Registro atualizado."); setOpen(false); }, onError: error => toast.error(error.message) }); return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button variant="outline" size="sm"><Pencil className="mr-2 h-3.5 w-3.5"/>Editar</Button></DialogTrigger><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Editar registro</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Tipo</Label><Select value={form.type} onValueChange={value => setForm({ ...form, type: value as typeof form.type })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="contract">Contrato</SelectItem><SelectItem value="bid">Licitação</SelectItem><SelectItem value="expense">Despesa</SelectItem><SelectItem value="revenue">Receita</SelectItem></SelectContent></Select></div><div className="space-y-2"><Label>Data</Label><Input type="date" value={form.eventDate} onChange={event => setForm({ ...form, eventDate: event.target.value })}/></div></div><div className="space-y-2"><Label>Título</Label><Input value={form.title} onChange={event => setForm({ ...form, title: event.target.value })}/></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Categoria</Label><Input value={form.category} onChange={event => setForm({ ...form, category: event.target.value })}/></div><div className="space-y-2"><Label>Valor (R$)</Label><Input type="number" value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })}/></div></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Referência</Label><Input value={form.referenceNumber} onChange={event => setForm({ ...form, referenceNumber: event.target.value })}/></div><div className="space-y-2"><Label>Situação</Label><Input value={form.status} onChange={event => setForm({ ...form, status: event.target.value })}/></div></div><div className="space-y-2"><Label>Fornecedor / favorecido</Label><Input value={form.supplier} onChange={event => setForm({ ...form, supplier: event.target.value })}/></div><div className="space-y-2"><Label>Descrição</Label><Textarea value={form.description} onChange={event => setForm({ ...form, description: event.target.value })}/></div></div><DialogFooter><Button disabled={!tenantId || update.isPending} onClick={() => tenantId && update.mutate({ id: record.id, tenantId, ...form, amount: Number(form.amount), referenceNumber: form.referenceNumber || undefined, supplier: form.supplier || undefined, description: form.description || undefined })} className="bg-[#0b6672]">Salvar alterações</Button></DialogFooter></DialogContent></Dialog>; }

function ServiceEditDialog({ service }: { service: { id: number; name: string; category: string; description: string; accessInstructions: string; digitalUrl: string | null; phone: string | null; public: boolean; active: boolean } }) { const { tenantId } = useMunicipality(); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: service.name, category: service.category, description: service.description, accessInstructions: service.accessInstructions, digitalUrl: service.digitalUrl ?? "", phone: service.phone ?? "", public: service.public, active: service.active }); const update = trpc.municipal.admin.updateService.useMutation({ onSuccess: () => { if (tenantId) { utils.municipal.admin.services.invalidate({ tenantId }); utils.municipal.public.services.invalidate(); } toast.success("Serviço atualizado."); setOpen(false); }, onError: error => toast.error(error.message) }); return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button variant="outline" size="sm"><Pencil className="mr-2 h-3.5 w-3.5"/>Editar</Button></DialogTrigger><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Editar serviço</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Nome</Label><Input value={form.name} onChange={event => setForm({ ...form, name: event.target.value })}/></div><div className="space-y-2"><Label>Categoria</Label><Input value={form.category} onChange={event => setForm({ ...form, category: event.target.value })}/></div></div><div className="space-y-2"><Label>Descrição</Label><Textarea value={form.description} onChange={event => setForm({ ...form, description: event.target.value })}/></div><div className="space-y-2"><Label>Como acessar</Label><Textarea value={form.accessInstructions} onChange={event => setForm({ ...form, accessInstructions: event.target.value })}/></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Link digital</Label><Input value={form.digitalUrl} onChange={event => setForm({ ...form, digitalUrl: event.target.value })}/></div><div className="space-y-2"><Label>Telefone</Label><Input value={form.phone} onChange={event => setForm({ ...form, phone: event.target.value })}/></div></div></div><DialogFooter><Button disabled={!tenantId || update.isPending} onClick={() => tenantId && update.mutate({ id: service.id, tenantId, ...form, digitalUrl: form.digitalUrl || undefined, phone: form.phone || undefined })} className="bg-[#0b6672]">Salvar alterações</Button></DialogFooter></DialogContent></Dialog>; }

function AdminOverview() { const { tenantId } = useMunicipality(); const input = useMemo(() => ({ tenantId: tenantId ?? "" }), [tenantId]); const query = trpc.municipal.admin.overview.useQuery(input, { enabled: Boolean(tenantId) }); if (!tenantId) return <EmptyAdminState />; if (query.isLoading) return <LoadingBlock label="Carregando visão administrativa" />; const data = query.data; return <><Header eyebrow="Painel administrativo" title="Uma leitura operacional da cidade" description="Acompanhe a composição das informações publicadas e mantenha os módulos municipais atualizados."/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={UsersRound} label="População" value={data?.stats?.population ? number.format(data.stats.population) : "—"} color="blue"/><Stat icon={CircleDollarSign} label="Receitas" value={data?.stats?.revenues ? currency.format(data.stats.revenues) : "—"} color="green"/><Stat icon={WalletCards} label="Despesas" value={data?.stats?.expenses ? currency.format(data.stats.expenses) : "—"} color="orange"/><Stat icon={Target} label="Projetos ativos" value={String(data?.stats?.activeProjects ?? 0)}/></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><AdminCard><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-semibold text-[#173c40]">Qualidade de publicação</h2><p className="mt-1 text-xs text-[#71878a]">Módulos com informação já registrada.</p></div><BarChart3 className="h-5 w-5 text-[#0b7a73]"/></div><div className="mt-6 space-y-4">{[["Indicadores", data?.indicators.length ?? 0], ["Registros de transparência", data?.transparencyCount ?? 0], ["Serviços municipais", data?.servicesCount ?? 0]].map(([label, value]) => <div key={String(label)} className="flex items-center justify-between border-b border-[#eef3f2] pb-3 text-sm last:border-0"><span className="text-[#61787b]">{label}</span><span className="font-semibold text-[#173c40]">{value}</span></div>)}</div></AdminCard><AdminCard className="bg-[#073f46] text-white"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#a6d8d0]">Orientação inicial</p><h2 className="mt-3 font-display text-2xl font-semibold tracking-[-.04em]">Comece pela prefeitura e pelos dados oficiais.</h2><p className="mt-3 text-sm leading-6 text-[#c0dedd]">As telas públicas exibem apenas informações que forem cadastradas e marcadas como públicas pela administração.</p><div className="mt-6 grid gap-3 sm:grid-cols-3"><span className="rounded-xl bg-white/10 p-3 text-xs text-[#dff4ef]">1. Cadastre projetos</span><span className="rounded-xl bg-white/10 p-3 text-xs text-[#dff4ef]">2. Atualize indicadores</span><span className="rounded-xl bg-white/10 p-3 text-xs text-[#dff4ef]">3. Publique transparência</span></div></AdminCard></div></>; }

function MunicipalitiesAdmin() { const { municipalities, selectMunicipality } = useMunicipality(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: "", state: "", population: "" }); const utils = trpc.useUtils(); const create = trpc.municipal.admin.createMunicipality.useMutation({ onSuccess: municipality => { selectMunicipality(municipality.id); utils.municipal.public.municipalities.invalidate(); toast.success("Prefeitura cadastrada com sucesso."); setOpen(false); setForm({ name: "", state: "", population: "" }); }, onError: error => toast.error(error.message) }); return <><Header eyebrow="Administração" title="Prefeituras e contexto municipal" description="Cada conjunto de dados é isolado por prefeitura. Selecione a prefeitura ativa antes de gerir informações." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="bg-[#0b6672]"><Plus className="mr-2 h-4 w-4"/>Nova prefeitura</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Nova prefeitura</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="space-y-2"><Label>Nome da prefeitura</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Prefeitura de Exemplo"/></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>UF</Label><Input maxLength={2} value={form.state} onChange={e => setForm({ ...form, state: e.target.value.toUpperCase() })} placeholder="SP"/></div><div className="space-y-2"><Label>População</Label><Input type="number" value={form.population} onChange={e => setForm({ ...form, population: e.target.value })} placeholder="0"/></div></div></div><DialogFooter><Button disabled={create.isPending} onClick={() => create.mutate({ name: form.name, state: form.state, population: form.population ? Number(form.population) : undefined })} className="bg-[#0b6672]">Criar prefeitura</Button></DialogFooter></DialogContent></Dialog>}/> <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{municipalities.map(municipality => <button key={municipality.id} onClick={() => { selectMunicipality(municipality.id); toast.success(`${municipality.name} selecionada.`); }} className="rounded-2xl border border-[#dce9e7] bg-white p-6 text-left shadow-[0_10px_24px_rgba(15,68,72,.04)] transition hover:-translate-y-0.5 hover:border-[#a9d7d1]"><div className="flex items-center justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e4f3f0] text-[#087069]"><Building2 className="h-5 w-5"/></span><Badge className="border-0 bg-[#eff6f5] text-[#087069]">{municipality.state}</Badge></div><h2 className="mt-6 font-display text-xl font-semibold tracking-[-.03em] text-[#173c40]">{municipality.name}</h2><p className="mt-2 text-sm text-[#71878a]">{municipality.population ? `${number.format(municipality.population)} habitantes` : "População não informada"}</p></button>)}{!municipalities.length && <EmptyAdminState title="Cadastre a primeira prefeitura" description="A prefeitura será a referência para todos os dados de transparência e gestão."/>}</div><MembershipSection /></>; }

function MembershipSection() { const { tenantId, activeMunicipality } = useMunicipality(); const input = useMemo(() => ({ tenantId: tenantId ?? "" }), [tenantId]); const query = trpc.municipal.admin.members.useQuery(input, { enabled: Boolean(tenantId) }); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ email: "", role: "viewer" as "viewer" | "editor" | "admin" }); const assign = trpc.municipal.admin.assignMember.useMutation({ onSuccess: () => { if (tenantId) utils.municipal.admin.members.invalidate({ tenantId }); toast.success("Vínculo municipal atualizado."); setOpen(false); setForm({ email: "", role: "viewer" }); }, onError: error => toast.error(error.message) }); const remove = trpc.municipal.admin.removeMember.useMutation({ onSuccess: () => { if (tenantId) utils.municipal.admin.members.invalidate({ tenantId }); toast.success("Vínculo removido."); }, onError: error => toast.error(error.message) }); if (!tenantId) return null; return <section className="mt-6"><AdminCard><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#0b7a73]">Acesso por prefeitura</p><h2 className="mt-2 font-display text-2xl font-semibold text-[#173c40]">Membros de {activeMunicipality?.name ?? "prefeitura ativa"}</h2><p className="mt-2 max-w-xl text-sm leading-6 text-[#71878a]">Usuários precisam autenticar-se antes de serem vinculados. O perfil determina se podem apenas consultar, editar ou administrar os dados desta prefeitura.</p></div><Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="bg-[#0b6672]"><Plus className="mr-2 h-4 w-4"/>Adicionar membro</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Vincular usuário</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="space-y-2"><Label>E-mail da conta autenticada</Label><Input type="email" value={form.email} onChange={event => setForm({ ...form, email: event.target.value })} placeholder="pessoa@prefeitura.gov.br"/></div><div className="space-y-2"><Label>Perfil nesta prefeitura</Label><Select value={form.role} onValueChange={value => setForm({ ...form, role: value as typeof form.role })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="viewer">viewer — consulta</SelectItem><SelectItem value="editor">editor — gestão de dados</SelectItem><SelectItem value="admin">admin — administração</SelectItem></SelectContent></Select></div></div><DialogFooter><Button disabled={assign.isPending} onClick={() => assign.mutate({ tenantId, ...form })} className="bg-[#0b6672]">Salvar vínculo</Button></DialogFooter></DialogContent></Dialog></div>{query.isLoading ? <div className="mt-5"><LoadingBlock label="Carregando membros" /></div> : query.isError ? <div className="mt-5"><QueryErrorState onRetry={() => query.refetch()} title="Não foi possível consultar os membros" /></div> : query.data?.length ? <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[620px] text-left"><thead className="bg-[#f4f8f7] text-[10px] font-bold uppercase tracking-[.12em] text-[#71878a]"><tr><th className="px-3 py-3">Nome</th><th className="px-3 py-3">E-mail</th><th className="px-3 py-3">Perfil</th><th className="px-3 py-3 text-right">Ações</th></tr></thead><tbody>{query.data.map(member => <tr key={member.id} className="border-t border-[#edf3f2] text-sm"><td className="px-3 py-3 font-semibold text-[#173c40]">{member.name || "Usuário"}</td><td className="px-3 py-3 text-[#61787b]">{member.email || "Não informado"}</td><td className="px-3 py-3"><Status status={member.role}/></td><td className="px-3 py-3 text-right"><Button variant="ghost" size="sm" disabled={remove.isPending} onClick={() => remove.mutate({ tenantId, membershipId: member.id })} className="text-[#b4564e] hover:bg-[#fff0ee] hover:text-[#97423c]">Remover</Button></td></tr>)}</tbody></table></div> : <p className="mt-5 rounded-xl bg-[#f4f8f7] p-4 text-sm text-[#71878a]">Ainda não há membros vinculados a esta prefeitura.</p>}</AdminCard></section>; }

function ProjectsAdmin() { const { tenantId } = useMunicipality(); const input = useMemo(() => ({ tenantId: tenantId ?? "" }), [tenantId]); const query = trpc.municipal.admin.projects.useQuery(input, { enabled: Boolean(tenantId) }); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<number | null>(null); const initial = { title: "", area: "", description: "", status: "planejado" as "planejado" | "em andamento" | "concluído" | "cancelado", progress: "0", startDate: "", targetDate: "", budget: "", public: true }; const [form, setForm] = useState(initial); const create = trpc.municipal.admin.createProject.useMutation({ onSuccess: () => { utils.municipal.admin.projects.invalidate(input); utils.municipal.admin.overview.invalidate(input); toast.success("Projeto cadastrado."); close(); }, onError: err => toast.error(err.message) }); const update = trpc.municipal.admin.updateProject.useMutation({ onSuccess: () => { utils.municipal.admin.projects.invalidate(input); toast.success("Projeto atualizado."); close(); }, onError: err => toast.error(err.message) }); const close = () => { setOpen(false); setEditing(null); setForm(initial); }; const openEdit = (project: NonNullable<typeof query.data>[number]) => { setEditing(project.id); setForm({ title: project.title, area: project.area, description: project.description ?? "", status: project.status, progress: String(project.progress), startDate: project.startDate ?? "", targetDate: project.targetDate ?? "", budget: project.budget ? String(project.budget) : "", public: project.public }); setOpen(true); }; const submit = () => { if (!tenantId) return; const values = { tenantId, title: form.title, area: form.area, description: form.description || undefined, status: form.status, progress: Number(form.progress), startDate: form.startDate || undefined, targetDate: form.targetDate || undefined, budget: form.budget ? Number(form.budget) : undefined, public: form.public }; if (editing) update.mutate({ id: editing, ...values }); else create.mutate(values); }; return <><Header eyebrow="Metas e projetos" title="Acompanhe as entregas municipais" description="Cadastre iniciativas, defina o andamento e publique somente as informações adequadas à consulta pública." action={<Dialog open={open} onOpenChange={value => value ? setOpen(true) : close()}><DialogTrigger asChild><Button disabled={!tenantId} className="bg-[#0b6672]"><Plus className="mr-2 h-4 w-4"/>Novo projeto</Button></DialogTrigger><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{editing ? "Editar projeto" : "Novo projeto"}</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="space-y-2"><Label>Nome do projeto</Label><Input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })}/></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Área responsável</Label><Input value={form.area} onChange={e => setForm({ ...form, area: e.target.value })} placeholder="Ex.: Infraestrutura"/></div><div className="space-y-2"><Label>Status</Label><Select value={form.status} onValueChange={value => setForm({ ...form, status: value as typeof form.status })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="planejado">planejado</SelectItem><SelectItem value="em andamento">em andamento</SelectItem><SelectItem value="concluído">concluído</SelectItem><SelectItem value="cancelado">cancelado</SelectItem></SelectContent></Select></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Progresso (%)</Label><Input type="number" min="0" max="100" value={form.progress} onChange={e => setForm({ ...form, progress: e.target.value })}/></div><div className="space-y-2"><Label>Orçamento estimado (R$)</Label><Input type="number" min="0" value={form.budget} onChange={e => setForm({ ...form, budget: e.target.value })}/></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Início</Label><Input type="date" value={form.startDate} onChange={e => setForm({ ...form, startDate: e.target.value })}/></div><div className="space-y-2"><Label>Prazo</Label><Input type="date" value={form.targetDate} onChange={e => setForm({ ...form, targetDate: e.target.value })}/></div></div><div className="space-y-2"><Label>Descrição</Label><Textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })}/></div></div><DialogFooter><Button disabled={create.isPending || update.isPending} onClick={submit} className="bg-[#0b6672]">{editing ? "Salvar alterações" : "Cadastrar projeto"}</Button></DialogFooter></DialogContent></Dialog>}/> {!tenantId ? <EmptyAdminState /> : query.isLoading ? <LoadingBlock /> : query.data?.length ? <div className="grid gap-4">{query.data.map(project => <AdminCard key={project.id}><div className="flex flex-col gap-5 sm:flex-row sm:items-start sm:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><Status status={project.status}/><span className="text-xs text-[#778d90]">{project.area}</span></div><h2 className="mt-3 font-display text-xl font-semibold tracking-[-.03em] text-[#173c40]">{project.title}</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#687f82]">{project.description || "Sem descrição complementar."}</p></div><Button variant="outline" size="sm" onClick={() => openEdit(project)}><Pencil className="mr-2 h-3.5 w-3.5"/>Editar</Button></div><div className="mt-5 grid gap-4 border-t border-[#edf3f2] pt-4 sm:grid-cols-[1fr_auto_auto]"><div><div className="h-2 overflow-hidden rounded-full bg-[#e7f0ef]"><div className="h-full rounded-full bg-[#0b7a73]" style={{ width: `${project.progress}%` }}/></div><p className="mt-2 text-xs font-semibold text-[#487174]">{project.progress}% de progresso</p></div><p className="text-xs text-[#71878a]">Prazo: <span className="font-semibold text-[#4b696d]">{dateText(project.targetDate)}</span></p><p className="text-xs text-[#71878a]">Orçamento: <span className="font-semibold text-[#4b696d]">{project.budget ? currency.format(Number(project.budget)) : "—"}</span></p></div></AdminCard>)}</div> : <EmptyAdminState title="Nenhum projeto cadastrado" description="Registre metas e projetos para acompanhar o andamento e apresentar iniciativas à população." />}</>; }

function IndicatorsAdmin() { const { tenantId } = useMunicipality(); const input = useMemo(() => ({ tenantId: tenantId ?? "" }), [tenantId]); const query = trpc.municipal.admin.indicators.useQuery(input, { enabled: Boolean(tenantId) }); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [measureOpen, setMeasureOpen] = useState(false); const [form, setForm] = useState({ name: "", area: "", unit: "", description: "", public: true }); const [measurement, setMeasurement] = useState({ indicatorId: "", value: "", referenceDate: "", source: "", quality: "unknown" as "validated" | "pending" | "unknown", notes: "" }); const create = trpc.municipal.admin.createIndicator.useMutation({ onSuccess: () => { utils.municipal.admin.indicators.invalidate(input); utils.municipal.admin.overview.invalidate(input); toast.success("Indicador cadastrado."); setOpen(false); setForm({ name: "", area: "", unit: "", description: "", public: true }); }, onError: err => toast.error(err.message) }); const createMeasurement = trpc.municipal.admin.createMeasurement.useMutation({ onSuccess: () => { utils.municipal.admin.indicators.invalidate(input); toast.success("Medição adicionada."); setMeasureOpen(false); }, onError: err => toast.error(err.message) }); return <><Header eyebrow="Indicadores" title="Medições que sustentam a gestão" description="Defina indicadores por área e registre medições periódicas, com fonte e nível de qualidade." action={<div className="flex gap-2"><Dialog open={measureOpen} onOpenChange={setMeasureOpen}><DialogTrigger asChild><Button disabled={!tenantId || !query.data?.indicators.length} variant="outline"><Plus className="mr-2 h-4 w-4"/>Medição</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Registrar medição</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="space-y-2"><Label>Indicador</Label><Select value={measurement.indicatorId} onValueChange={value => setMeasurement({ ...measurement, indicatorId: value })}><SelectTrigger><SelectValue placeholder="Selecionar indicador"/></SelectTrigger><SelectContent>{query.data?.indicators.map(indicator => <SelectItem key={indicator.id} value={String(indicator.id)}>{indicator.name}</SelectItem>)}</SelectContent></Select></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Valor</Label><Input type="number" value={measurement.value} onChange={e => setMeasurement({ ...measurement, value: e.target.value })}/></div><div className="space-y-2"><Label>Data de referência</Label><Input type="date" value={measurement.referenceDate} onChange={e => setMeasurement({ ...measurement, referenceDate: e.target.value })}/></div></div><div className="space-y-2"><Label>Fonte</Label><Input value={measurement.source} onChange={e => setMeasurement({ ...measurement, source: e.target.value })} placeholder="Ex.: Secretaria Municipal"/></div><div className="space-y-2"><Label>Qualidade</Label><Select value={measurement.quality} onValueChange={value => setMeasurement({ ...measurement, quality: value as typeof measurement.quality })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="validated">validado</SelectItem><SelectItem value="pending">pendente</SelectItem><SelectItem value="unknown">não informado</SelectItem></SelectContent></Select></div></div><DialogFooter><Button onClick={() => tenantId && createMeasurement.mutate({ tenantId, indicatorId: Number(measurement.indicatorId), value: Number(measurement.value), referenceDate: measurement.referenceDate, source: measurement.source, quality: measurement.quality, notes: measurement.notes || undefined })} className="bg-[#0b6672]">Salvar medição</Button></DialogFooter></DialogContent></Dialog><Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button disabled={!tenantId} className="bg-[#0b6672]"><Plus className="mr-2 h-4 w-4"/>Indicador</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Novo indicador</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="space-y-2"><Label>Nome</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })}/></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Secretaria ou área</Label><Input value={form.area} onChange={e => setForm({ ...form, area: e.target.value })}/></div><div className="space-y-2"><Label>Unidade</Label><Input value={form.unit} onChange={e => setForm({ ...form, unit: e.target.value })} placeholder="%, R$, unidades"/></div></div><div className="space-y-2"><Label>Descrição</Label><Textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })}/></div></div><DialogFooter><Button onClick={() => tenantId && create.mutate({ tenantId, ...form, description: form.description || undefined })} className="bg-[#0b6672]">Cadastrar indicador</Button></DialogFooter></DialogContent></Dialog></div>}/> {!tenantId ? <EmptyAdminState /> : query.isLoading ? <LoadingBlock /> : query.isError ? <QueryErrorState onRetry={() => query.refetch()} title="Indicadores indisponíveis" description="Não foi possível recuperar os indicadores administrativos. Tente novamente em instantes." /> : query.data?.indicators.length ? <div className="grid gap-4 md:grid-cols-2">{query.data.indicators.map(indicator => <AdminCard key={indicator.id}><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#0b7a73]">Secretaria ou área · {indicator.area}</p><h2 className="mt-2 font-display text-xl font-semibold text-[#173c40]">{indicator.name}</h2></div><div className="flex items-center gap-2"><Badge className="border-0 bg-[#eef6f5] text-[#087069]">{indicator.unit}</Badge><IndicatorEditDialog indicator={indicator}/></div></div><p className="mt-3 text-sm leading-6 text-[#687f82]">{indicator.description || "Sem descrição."}</p><div className="mt-5 border-t border-[#edf3f2] pt-4"><p className="font-display text-3xl font-semibold text-[#173c40]">{indicator.latestMeasurement ? number.format(Number(indicator.latestMeasurement.value)) : "—"}<span className="ml-2 text-sm font-sans font-medium text-[#71878a]">{indicator.unit}</span></p><p className="mt-2 text-xs text-[#7c9294]">Última medição: {indicator.latestMeasurement ? dateText(indicator.latestMeasurement.referenceDate) : "Não registrada"}</p>{indicator.history.length > 1 ? <div className="mt-4 h-36 rounded-xl bg-[#f4f8f7] p-2"><ResponsiveContainer width="100%" height="100%"><AreaChart data={indicator.history}><defs><linearGradient id={`admin-indicator-${indicator.id}`} x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#0b7a73" stopOpacity=".3"/><stop offset="100%" stopColor="#0b7a73" stopOpacity="0"/></linearGradient></defs><CartesianGrid vertical={false} stroke="#e5efed"/><XAxis dataKey="referenceDate" tickFormatter={(value: string) => dateText(value).split(" ").slice(0, 2).join(" ")} axisLine={false} tickLine={false} tick={{ fill: "#708689", fontSize: 9 }}/><YAxis hide/><Tooltip formatter={(value: number) => `${number.format(value)} ${indicator.unit}`} labelFormatter={dateText}/><Area type="monotone" dataKey="value" stroke="#0b7a73" fill={`url(#admin-indicator-${indicator.id})`} strokeWidth={2}/></AreaChart></ResponsiveContainer></div> : <p className="mt-4 text-xs text-[#7c9294]">Histórico em formação: registre uma segunda medição para visualizar a evolução.</p>}{indicator.history.length ? <div className="mt-4 overflow-hidden rounded-xl border border-[#e4efed]"><div className="grid grid-cols-[.9fr_.8fr_1.2fr_auto] gap-2 bg-[#f4f8f7] px-3 py-2 text-[9px] font-bold uppercase tracking-[.1em] text-[#71878a]"><span>Data</span><span>Valor</span><span>Fonte</span><span>Qualidade</span></div>{indicator.history.slice().reverse().slice(0, 5).map(measurementRow => <div key={measurementRow.id} className="grid grid-cols-[.9fr_.8fr_1.2fr_auto] gap-2 border-t border-[#edf3f2] px-3 py-2 text-[10px] text-[#60777a]"><span>{dateText(measurementRow.referenceDate)}</span><span className="font-semibold text-[#274c51]">{number.format(Number(measurementRow.value))}</span><span className="truncate">{measurementRow.source}</span><span><Status status={measurementRow.quality}/></span></div>)}</div> : null}</div></AdminCard>)}</div> : <EmptyAdminState title="Nenhum indicador cadastrado" description="Crie os indicadores prioritários e depois registre suas medições periódicas." />}</>; }

function TransparencyAdmin() { const { tenantId } = useMunicipality(); const input = useMemo(() => ({ tenantId: tenantId ?? "" }), [tenantId]); const query = trpc.municipal.admin.transparency.useQuery(input, { enabled: Boolean(tenantId) }); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ type: "expense" as "contract" | "bid" | "expense" | "revenue", title: "", referenceNumber: "", category: "", supplier: "", amount: "", eventDate: "", status: "", description: "" }); const create = trpc.municipal.admin.createTransparency.useMutation({ onSuccess: () => { utils.municipal.admin.transparency.invalidate(input); utils.municipal.admin.overview.invalidate(input); utils.municipal.public.transparency.invalidate(); toast.success("Registro de transparência publicado."); setOpen(false); }, onError: err => toast.error(err.message) }); return <><Header eyebrow="Transparência" title="Registros públicos municipais" description="Cadastre contratos, licitações, despesas ou receitas para disponibilizá-los na área de consulta cidadã." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button disabled={!tenantId} className="bg-[#0b6672]"><Plus className="mr-2 h-4 w-4"/>Novo registro</Button></DialogTrigger><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Publicar registro</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Tipo</Label><Select value={form.type} onValueChange={value => setForm({ ...form, type: value as typeof form.type })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="contract">Contrato</SelectItem><SelectItem value="bid">Licitação</SelectItem><SelectItem value="expense">Despesa</SelectItem><SelectItem value="revenue">Receita</SelectItem></SelectContent></Select></div><div className="space-y-2"><Label>Data</Label><Input type="date" value={form.eventDate} onChange={e => setForm({ ...form, eventDate: e.target.value })}/></div></div><div className="space-y-2"><Label>Título</Label><Input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })}/></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Categoria</Label><Input value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}/></div><div className="space-y-2"><Label>Valor (R$)</Label><Input type="number" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })}/></div></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Referência</Label><Input value={form.referenceNumber} onChange={e => setForm({ ...form, referenceNumber: e.target.value })}/></div><div className="space-y-2"><Label>Situação</Label><Input value={form.status} onChange={e => setForm({ ...form, status: e.target.value })}/></div></div><div className="space-y-2"><Label>Fornecedor / favorecido</Label><Input value={form.supplier} onChange={e => setForm({ ...form, supplier: e.target.value })}/></div></div><DialogFooter><Button onClick={() => tenantId && create.mutate({ tenantId, ...form, amount: Number(form.amount), referenceNumber: form.referenceNumber || undefined, supplier: form.supplier || undefined, description: form.description || undefined, public: true })} className="bg-[#0b6672]">Publicar registro</Button></DialogFooter></DialogContent></Dialog>}/> {!tenantId ? <EmptyAdminState /> : query.isLoading ? <LoadingBlock /> : query.data?.records.length ? <div className="overflow-hidden rounded-2xl border border-[#dce9e7] bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead className="bg-[#f3f8f7] text-[10px] font-bold uppercase tracking-[.13em] text-[#71878a]"><tr><th className="px-5 py-4">Registro</th><th className="px-5 py-4">Categoria</th><th className="px-5 py-4">Data</th><th className="px-5 py-4">Valor</th><th className="px-5 py-4 text-right">Ações</th></tr></thead><tbody>{query.data.records.map(record => <tr key={record.id} className="border-t border-[#edf3f2] text-sm"><td className="px-5 py-4"><p className="font-semibold text-[#173c40]">{record.title}</p><p className="mt-1 text-xs text-[#7c9294]">{record.type} · {record.status}</p></td><td className="px-5 py-4 text-[#61787b]">{record.category}</td><td className="px-5 py-4 text-[#61787b]">{dateText(record.eventDate)}</td><td className="px-5 py-4 font-semibold text-[#173c40]">{currency.format(Number(record.amount))}</td><td className="px-5 py-4 text-right"><TransparencyEditDialog record={record}/></td></tr>)}</tbody></table></div></div> : <EmptyAdminState title="Nenhum registro publicado" description="Cadastre contratos, licitações, despesas e receitas para iniciar a prestação de contas pública." />}</>; }

function ServicesAdmin() { const { tenantId } = useMunicipality(); const input = useMemo(() => ({ tenantId: tenantId ?? "" }), [tenantId]); const query = trpc.municipal.admin.services.useQuery(input, { enabled: Boolean(tenantId) }); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: "", category: "", description: "", accessInstructions: "", digitalUrl: "", phone: "" }); const create = trpc.municipal.admin.createService.useMutation({ onSuccess: () => { utils.municipal.admin.services.invalidate(input); utils.municipal.admin.overview.invalidate(input); utils.municipal.public.services.invalidate(); toast.success("Serviço cadastrado."); setOpen(false); }, onError: err => toast.error(err.message) }); return <><Header eyebrow="Serviços municipais" title="Organize os serviços à população" description="Cadastre informações de acesso, canais digitais e orientações para cada serviço oferecido." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button disabled={!tenantId} className="bg-[#0b6672]"><Plus className="mr-2 h-4 w-4"/>Novo serviço</Button></DialogTrigger><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Novo serviço</DialogTitle></DialogHeader><div className="grid gap-4 py-3"><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Nome</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })}/></div><div className="space-y-2"><Label>Categoria</Label><Input value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}/></div></div><div className="space-y-2"><Label>Descrição</Label><Textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })}/></div><div className="space-y-2"><Label>Como acessar</Label><Textarea value={form.accessInstructions} onChange={e => setForm({ ...form, accessInstructions: e.target.value })}/></div><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Link digital</Label><Input value={form.digitalUrl} onChange={e => setForm({ ...form, digitalUrl: e.target.value })} placeholder="https://"/></div><div className="space-y-2"><Label>Telefone</Label><Input value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })}/></div></div></div><DialogFooter><Button onClick={() => tenantId && create.mutate({ tenantId, ...form, digitalUrl: form.digitalUrl || undefined, phone: form.phone || undefined, public: true, active: true })} className="bg-[#0b6672]">Cadastrar serviço</Button></DialogFooter></DialogContent></Dialog>}/> {!tenantId ? <EmptyAdminState /> : query.isLoading ? <LoadingBlock /> : query.data?.services.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{query.data.services.map(service => <AdminCard key={service.id}><div className="flex items-center justify-between"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#e4f3f0] text-[#087069]"><Wrench className="h-4 w-4"/></span><Badge className="border-0 bg-[#f0f6f5] text-[#4b7073]">{service.category}</Badge></div><h2 className="mt-5 font-display text-xl font-semibold text-[#173c40]">{service.name}</h2><p className="mt-3 text-sm leading-6 text-[#687f82]">{service.description}</p><p className="mt-4 border-t border-[#edf3f2] pt-3 text-xs leading-5 text-[#71878a]">{service.accessInstructions}</p><div className="mt-4"><ServiceEditDialog service={service}/></div></AdminCard>)}</div> : <EmptyAdminState title="Nenhum serviço cadastrado" description="Inclua os serviços para que a população encontre orientações e canais de atendimento." />}</>; }

function ReceiptsAdmin() { const { tenantId } = useMunicipality(); const input = useMemo(() => ({ tenantId: tenantId ?? "" }), [tenantId]); const query = trpc.municipal.admin.receipts.useQuery(input, { enabled: Boolean(tenantId) }); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ resource: "", operation: "manual" as "snapshot" | "incremental" | "manual", idempotencyKey: `manual-${Date.now()}`, records: "[\n  {\n    \"id\": \"registro-001\"\n  }\n]" }); const create = trpc.municipal.admin.recordReceipt.useMutation({ onSuccess: result => { if (tenantId) utils.municipal.admin.receipts.invalidate({ tenantId }); toast.success(result.duplicate ? "Esta chave já havia sido processada." : "Recebimento registrado com sucesso."); setOpen(false); setForm({ resource: "", operation: "manual", idempotencyKey: `manual-${Date.now()}`, records: "[\n  {\n    \"id\": \"registro-001\"\n  }\n]" }); }, onError: error => toast.error(error.message) }); const submit = () => { if (!tenantId) return; try { const parsed = JSON.parse(form.records); if (!Array.isArray(parsed) || !parsed.length || parsed.some(item => !item || typeof item !== "object" || Array.isArray(item))) throw new Error("O conteúdo deve ser uma lista JSON de objetos."); create.mutate({ tenantId, source: "manual", resource: form.resource, operation: form.operation, idempotencyKey: form.idempotencyKey, records: parsed as Record<string, unknown>[] }); } catch (error) { toast.error(error instanceof Error ? error.message : "JSON inválido."); } }; return <><Header eyebrow="Operação" title="Recebimentos e cargas de dados" description="Acompanhe lotes recebidos e registre cargas internas validadas. A integração oficial com fornecedores depende de contrato e documentação técnica próprios." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button disabled={!tenantId} className="bg-[#0b6672]"><Plus className="mr-2 h-4 w-4"/>Registrar carga</Button></DialogTrigger><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Registrar carga interna</DialogTitle></DialogHeader><p className="text-sm leading-6 text-[#687f82]">Use este fluxo para registrar uma carga autorizada. Ele valida o lote, grava o recibo e protege contra duplicidade por chave de idempotência.</p><div className="grid gap-4 py-3"><div className="grid grid-cols-2 gap-4"><div className="space-y-2"><Label>Recurso</Label><Input value={form.resource} onChange={event => setForm({ ...form, resource: event.target.value })} placeholder="Ex.: indicadores"/></div><div className="space-y-2"><Label>Operação</Label><Select value={form.operation} onValueChange={value => setForm({ ...form, operation: value as typeof form.operation })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="manual">manual</SelectItem><SelectItem value="snapshot">snapshot</SelectItem><SelectItem value="incremental">incremental</SelectItem></SelectContent></Select></div></div><div className="space-y-2"><Label>Chave de idempotência</Label><Input value={form.idempotencyKey} onChange={event => setForm({ ...form, idempotencyKey: event.target.value })}/></div><div className="space-y-2"><Label>Registros (JSON)</Label><Textarea className="min-h-40 font-mono text-xs" value={form.records} onChange={event => setForm({ ...form, records: event.target.value })}/></div></div><DialogFooter><Button disabled={create.isPending} onClick={submit} className="bg-[#0b6672]">Validar e registrar</Button></DialogFooter></DialogContent></Dialog>}/> {!tenantId ? <EmptyAdminState /> : query.isLoading ? <LoadingBlock /> : query.data?.length ? <div className="grid gap-4">{query.data.map(receipt => <AdminCard key={receipt.id}><div className="flex flex-wrap items-center justify-between gap-4"><div><div className="flex gap-2"><Status status={receipt.status}/><Badge className="border-0 bg-[#eef5f4] text-[#557477]">{receipt.source}</Badge></div><h2 className="mt-3 font-mono text-sm font-medium text-[#173c40]">{receipt.resource}</h2><p className="mt-1 text-xs text-[#71878a]">{receipt.operation} · recebido em {dateText(receipt.receivedAt)}</p></div><div className="text-right"><p className="text-xl font-semibold text-[#173c40]">{receipt.acceptedRecords}</p><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#71878a]">Registros aceitos</p></div></div></AdminCard>)}</div> : <AdminCard className="bg-[#f1f8f7]"><ReceiptText className="h-8 w-8 text-[#0b7a73]"/><h2 className="mt-4 font-display text-2xl font-semibold text-[#173c40]">Nenhum recebimento processado</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#687f82]">Registre uma carga interna para gerar um recibo auditável. O endpoint externo permanece condicionado a segredo de ambiente e autorização técnica da origem.</p></AdminCard>}</>; }

export default function AdminPages() { const [location] = useLocation(); let content: React.ReactNode; if (location === "/admin/projetos") content = <ProjectsAdmin/>; else if (location === "/admin/indicadores") content = <IndicatorsAdmin/>; else if (location === "/admin/transparencia") content = <TransparencyAdmin/>; else if (location === "/admin/servicos") content = <ServicesAdmin/>; else if (location === "/admin/recebimentos") content = <ReceiptsAdmin/>; else if (location === "/admin/prefeituras") content = <MunicipalityAccessSetup/>; else if (location === "/admin/tributos/arrecadacao") content = <TaxPages view="arrecadacao"/>; else if (location === "/admin/tributos/iptu") content = <TaxPages view="iptu"/>; else if (location === "/admin/tributos/iss") content = <TaxPages view="iss"/>; else if (location === "/admin/tributos/itbi") content = <TaxPages view="itbi"/>; else if (location === "/admin/tributos/inadimplencia") content = <TaxPages view="inadimplencia"/>; else if (location === "/admin/tributos/divida-ativa") content = <TaxPages view="divida"/>; else if (location === "/admin/tributos/parcelamentos") content = <TaxPhaseTwoPages view="parcelamentos"/>; else if (location === "/admin/tributos/fiscalizacao") content = <TaxPhaseTwoPages view="fiscalizacao"/>; else if (location === "/admin/tributos/contribuintes") content = <TaxPhaseTwoPages view="contribuintes"/>; else if (location === "/admin/tributos") content = <TaxPages view="geral"/>; else content = <AdminOverview/>; return <DashboardLayout>{content}</DashboardLayout>; }
